#include <bits/stdc++.h>
using namespace std;
#define int long long

signed main() {
	// your code goes here
	int t;
	cin>>t;
	while(t--) {
	    int n;
	    cin>>n;
	    
	    vector<int> a(3 * n);
	    for(int i = 0; i<(3*n); i++) cin>>a[i];
	    
	    sort(a.rbegin(), a.rend());
	    
	    vector<int> pref(3 * n + 1);
	    
	    for(int i = 0; i< 3 * n; i++) pref[i+1] = pref[i] + a[i];
	    
	    auto calc = [&](int A, int B) {
	        int C = n - A - B;
	        int p1 = A;
	        int p2 = A + 2 * B;
	        int p3 = 3 * n - 2 * A - B;
	        return 6 * pref[p1] + 4 * (pref[p2] - pref[p1]) + 3 * (pref[p3] - pref[p2]);
	    };
	        
	        int ans = 0;
	        for(int A = 0; A<=n; A++) {
	            int lo = 0;
	            int hi = n - A;
	            while(lo < hi) {
	                int mid = (lo + hi ) / 2;
	                int k = A + 2 * mid;
	                int end = 3 * n - 2 * A - mid;
	                
	                int delta = a[k] + a[k + 1] - 3 * a[end - 1];
	                if(delta >= 0) lo = mid + 1;
	                else hi = mid;
	            }
	            int B;
	            if(lo == n - A) B = lo;
	            else B = max(0LL, lo - 1);
	            ans = max(ans, calc(A, B));
	            if(B + 1 <= n - A) ans = max(ans, calc(A,B+1));
	       
	       // if(lo + 1 <= n - A) ans = max(ans, calc(A, lo + 1));
	    }
	    cout<<ans<<"\n";
	    
	    
	    
	}

}
